const DOC_TYPES = [
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.ms-excel',
  'text/csv',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/msword',
];
const MIN_IMAGE_KB = 40; // signatures/logos are below this; covers/flyers above

function sizeKB(b) {
  const m = (b.fileSize || '').toString().match(/([\d.]+)\s*(kB|MB|B)\b/i);
  if (!m) return Infinity;
  const n = parseFloat(m[1]);
  const u = m[2].toUpperCase();
  return u === 'MB' ? n * 1024 : u === 'B' ? n / 1024 : n;
}

const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    const mime = (b.mimeType || '').toLowerCase();
    const isImage = mime.startsWith('image/');

    if (isImage && sizeKB(b) < MIN_IMAGE_KB) continue;   // drop only small images (signatures)
    if (!DOC_TYPES.includes(mime) && !isImage) continue; // ignore non-doc, non-image files

    out.push({
      json: { message_id: item.json.id, thread_id: item.json.threadId, filename: b.fileName || key },
      binary: { data: b },
    });
  }
}
return out;

// Group the parsed attachments of ONE email into a single Markdown blob for the AI.
// LlamaParse returns Markdown per page (p.md): tables, columns and headings survive,
// and a label price list IS a table — the flattened p.text loses the column alignment
// and makes the model guess which number is COP, PPD or rock bottom. p.text is kept
// only as a fallback for pages LlamaParse could not render as Markdown.
// Each file keeps its filename so two price lists in the same email stay apart.
const MAX = 40000;
const byEmail = {};
for (const item of $input.all()) {
  const id = item.json.message_id;
  const md = item.json.attachment_markdown || item.json.attachment_text || '';
  if (!md) continue;
  const name = item.json.filename || 'attachment';
  if (!byEmail[id]) byEmail[id] = [];
  byEmail[id].push('## Attachment: ' + name + '\n\n' + md);
}
return Object.keys(byEmail).map(function (id) {
  let blob = byEmail[id].join('\n\n---\n\n');
  // Truncate HERE (not in Set Fields) so the cut is visible instead of silent.
  if (blob.length > MAX) blob = blob.slice(0, MAX) + '\n\n[TRUNCATED — attachment content longer than ' + MAX + ' characters]';
  return { json: { message_id: id, attachments_text: blob } };
});

// Explode each relevant AI result into one row per catalog item, mapped to the REAL
// catalog_lines columns, and decide DETERMINISTICALLY (no AI) whether each item is a
// new line or an update to an existing one. v15: document type drives the catalog
// (invoice -> other, release -> main; orders never enter), digital releases are
// dropped, the label map is table-driven, and non-standard features are surfaced in
// the title.

function toCatalogCode(ean) {
  if (ean === null || ean === undefined) return null;
  const s = String(ean).replace(/\D/g, '');
  if (!s) return null;
  const trimmed = s.slice(0, -1).replace(/^0+/, '');
  return trimmed || null;
}

// Never trust the model: neither artist nor title may start OR end with "THE".
function dropThe(s) {
  if (typeof s !== 'string') return s;
  const orig = s;
  let t = s;
  while (t[0] === ' ') t = t.slice(1);
  if (t.slice(0, 4).toUpperCase() === 'THE ') { t = t.slice(4); while (t[0] === ' ') t = t.slice(1); }
  t = t.replace(/[\s,]+THE\s*$/i, '');
  while (t.length && t[t.length - 1] === ' ') t = t.slice(0, -1);
  return t === '' ? orig : t;
}

const VARIANT_RE = /\b(VINYL|LP|CD|MC|DIGI|DIGIPAK|DIGIPACK|LTD|LIMITED|EXCLUSIVE|INDIE|RSD|SIGNED|PICTURE|DISC|DIE-CUT|GATEFOLD|T-SHIRT|PATCH|BOXSET|BOX|DELUXE|EDITION|REISSUE|BLACK|WHITE|RED|GREEN|BLUE|YELLOW|GOLD|SILVER|CLEAR|ORANGE|PURPLE|PINK|GREY|GRAY|MARBLE|SPLATTER|GLITTER|TRANSPARENT|INKSPOT|GLOW|SLUDGE|OPAQUE|CRYSTAL|SOFTPAK|JEWEL|AMARAY|LIGHT)\b/;
function cleanTitle(s) {
  if (typeof s !== 'string') return { title: s, removed: [] };
  const removed = [];
  let t = s.replace(/\s*[\(\[]([^()\[\]]*)[\)\]]/g, function (m, inner) {
    if (VARIANT_RE.test(inner.toUpperCase())) { removed.push(inner.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s+[-–]\s+([^-–]+)$/, function (m, seg) {
    const words = seg.trim().toUpperCase().split(/[\s,\/&+]+/).filter(Boolean);
    if (words.length && words.every(function (w) { return VARIANT_RE.test(w) || /^[0-9]+$/.test(w); })) { removed.push(seg.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s{2,}/g, ' ').replace(/[\s,;:\-–]+$/, '').trim();
  return { title: t, removed: removed };
}
function up(s) { return typeof s === 'string' ? s.toUpperCase() : s; }

// Non-standard features from the product info are surfaced in the TITLE as "(FEATURE)"
// tokens, CAPS, in a fixed order: weight -> colour -> exclusive/special -> limited.
// Standard defaults (black vinyl, 140g, all retail) are never shown. The model supplies
// the raw non-standard features; this orders/formats them so the output is consistent
// no matter how the model lists them. No features -> the clean title as before.
const COLOUR_WORD = /^(RED|WHITE|BLUE|GREEN|YELLOW|GOLD|SILVER|CLEAR|ORANGE|PURPLE|PINK|GREY|GRAY|BROWN|CREAM|AMBER|TURQUOISE|MAGENTA|CRYSTAL|BONE|NATURAL|SMOKE|MARBLE|SPLATTER|GALAXY|GLITTER|COKE BOTTLE|SEA BLUE|BABY BLUE|ECORECORD)( VINYL)?$/;
function isStandardFeature(f) {
  return /^BLACK( VINYL)?$/.test(f) || /^140\s*G/.test(f) || /^(ALL RETAIL|RETAIL|STANDARD|REGULAR|VINYL|ALBUM|12"|1X ?LP|1 X 140G)$/.test(f);
}
function featureBucket(f) {
  if (/\d+\s*G(?:RAMS?)?\b/.test(f)) return 0;                                   // 180G
  if (/VINYL$/.test(f) || COLOUR_WORD.test(f) || /PICTURE DISC|GATEFOLD/.test(f)) return 1; // RED VINYL
  if (/\bLIMIT|\bLTD\b|\bNUMBERED\b/.test(f)) return 3;                          // LIMITED / LTD
  return 2;                                                                      // EXCLUSIVE / BLACK FRIDAY / RSD / SIGNED ...
}
function formatFeatures(features) {
  if (!Array.isArray(features)) return '';
  const seen = {};
  const buckets = [[], [], [], []];
  for (const raw of features) {
    if (typeof raw !== 'string') continue;
    const f = raw.trim().toUpperCase().replace(/^[\(\[]+/, '').replace(/[\)\]]+$/, '').trim();
    if (!f || isStandardFeature(f) || seen[f]) continue;
    seen[f] = true;
    buckets[featureBucket(f)].push(f);
  }
  const ordered = buckets[0].concat(buckets[1], buckets[2], buckets[3]);
  return ordered.map(function (f) { return ' (' + f + ')'; }).join('');
}

function labelKey(s) { return typeof s === 'string' ? s.toUpperCase().replace(/[^A-Z0-9]/g, '') : ''; }

// Supplier code (Hermes) is by LABEL. The catalog (main/other) is NOT decided here any
// more — document type decides it (see below). Codes not yet known are blank.
const SUPPLIER_CODES = {
  MATRIXMUSIC: '54', MATRIX: '54',
  PIASRECORDINGS: '1009', PIAS: '1009',
  IDIMUSIC: null, IDI: null,
  CROATIARECORDS: null, BELLES: null,
};
function supplierCodeFor(label) {
  const k = labelKey(label);
  return Object.prototype.hasOwnProperty.call(SUPPLIER_CODES, k) ? SUPPLIER_CODES[k] : '149';
}

// Raw label -> canonical, built from the Senders table (label_raw rows) the client
// maintains in Settings. CANONICAL = every canonical output, so an already-canonical
// label is never re-flagged as "unmapped".
const senderRows = $('Senders').all().map(function (i) { return i.json; });
const LABEL_MAP = {};
const CANONICAL = {};
for (const r of senderRows) {
  if (r && r.label) CANONICAL[labelKey(r.label)] = true;
  if (r && r.label_raw && r.label) LABEL_MAP[labelKey(r.label_raw)] = r.label;
}
['NONESUCH', 'ROADRUNNER', 'WARNER', 'PARLOPHONE'].forEach(function (x) { CANONICAL[labelKey(x)] = true; });

function keyEan(v) {
  const d = String(v === null || v === undefined ? '' : v).replace(/\D/g, '').replace(/^0+/, '');
  return d || '';
}
function keyCat(v) { return String(v === null || v === undefined ? '' : v).toUpperCase().replace(/[^A-Z0-9]/g, ''); }
function findMatch(pool, used, row) {
  const ean = keyEan(row.ean);
  const cat = keyCat(row.catalogue_no);
  const free = pool.filter(function (c) { return !used.has(c.id); });
  const eanOk = function (c) { const ce = keyEan(c.ean); return !ce || !ean || ce === ean; };
  const tiers = [];
  if (ean) tiers.push(['ean', free.filter(function (c) { return keyEan(c.ean) === ean; })]);
  if (cat) tiers.push(['catalogue_no', free.filter(function (c) { return keyCat(c.catalogue_no) === cat && eanOk(c); })]);
  for (const tier of tiers) {
    if (tier[1].length === 1) return { line: tier[1][0], via: tier[0] };
    if (tier[1].length > 1) return { ambiguous: tier[0], count: tier[1].length };
  }
  return null;
}

function isBlank(v) { return v === null || v === undefined || v === ''; }
function stripBlank(obj) { const out = {}; for (const k of Object.keys(obj)) if (!isBlank(obj[k])) out[k] = obj[k]; return out; }
function appendNote(existing, add) {
  const cur = String(existing === null || existing === undefined ? '' : existing).trim();
  if (!add) return cur || null;
  if (!cur) return add;
  if (cur.indexOf(add) !== -1) return cur;
  return cur + '\n' + add;
}

// calculation_group: force "1" unless an explicit budget/mid signal is printed.
const MIDBUDGET_RE = /\b(budget|mid[-\s]?price|mid[-\s]?line|nice[-\s]?price|reduced[-\s]?price|low[-\s]?price|super[-\s]?budget)\b/i;
function calcGroup(item, src) {
  const g = String(item.calculation_group == null ? '' : item.calculation_group).trim();
  if (g !== '2' && g !== '3') return '1';
  const text = (item.item_notes || '') + '\n' + ((src && src.body) || '');
  return MIDBUDGET_RE.test(text) ? g : '1';
}

// "We are not sure" must NEVER become an exclusion.
const UNSURE_RE = /\b(UNCLEAR|UNCERTAIN|AMBIGUOUS|POSSIBLY|POTENTIALLY|PRESUMABLY|APPARENTLY|UNKNOWN|UNSPECIFIED|NOT SPECIFIED|NOT CLEAR|CANNOT BE DETERMINED)\b/i;
// Indie exclusivity is NOT a reason to exclude (client, 2026-07): those releases enter
// as in_progress. Only downgrade when "indie" is the ONLY exclusion signal.
const REAL_EXCL_RE = /\b(US|USA|CANADA|AMAZON|D2C|DIGITAL|WEB\s*STORE|EUROPE|EU ONLY|NORTH AMERICA)\b/i;
// Orders never enter the catalog (invoices DO -> Other). The model classifies from
// content; this is a deterministic backup on the SUBJECT only (never bare "order" —
// "pre-order" is a release). Slovenian included.
const ORDER_RE = /(purchase\s*order|naro[čc]ilo)/i;
const DIGITAL_RE = /\b(digital|download|streaming|stream)\b|\bDL\b/i;
const SENTINEL_DATE = '2099-12-31';

// Periodic summary emails (a weekly/monthly planner, a stock list) duplicate releases we
// already receive -> drop them. Deterministic: known sender + a subject keyword.
const PERIODIC = [
  { from: 'david.windmill@warnermusic.com', subject: 'planner' },
  { from: 'danutamorawska@mystic.pl', subject: 'stock' },
];
function isPeriodic(from, subject) {
  const f = String(from || '').toLowerCase();
  const s = String(subject || '').toLowerCase();
  return PERIODIC.some(function (p) { return f.indexOf(p.from) !== -1 && s.indexOf(p.subject) !== -1; });
}

const WATCHED = ['artist', 'title', 'format', 'unit', 'ean', 'catalogue_no', 'release_date', 'label', 'cop', 'ppd', 'rock_bottom', 'price_original', 'currency', 'calculation_group'];
const MANDATORY = $('MandatoryFields').all().map(function (i) { return i.json.field_name; }).filter(Boolean);
const allLines = $('Catalog Lines (matching)').all().map(function (i) { return i.json; });
const openPool = allLines.filter(function (l) { return !l.sent_at; });
const sentPool = allLines.filter(function (l) { return !!l.sent_at; });
const usedOpen = new Set();
const usedSent = new Set();
const createdEans = new Set();
const createdCatNos = new Set();

const rows = [];
const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  let result = inputs[i].json;
  result = result.output ?? result.message?.content ?? result.content ?? result;
  if (typeof result === 'string') { const a = result.indexOf('{'), b = result.lastIndexOf('}'); try { result = JSON.parse(a >= 0 && b > a ? result.slice(a, b + 1) : result); } catch (e) { continue; } }
  if (!result || result.is_catalog_relevant === false) continue;

  let src = {};
  try { src = $('Chunk Source').itemMatching(i).json; }
  catch (e) { try { src = $('Chunk Source').first().json; } catch (e2) {} }
  const stamp = String(src.date || '').slice(0, 10) || new Date().toISOString().slice(0, 10);

  // Orders and periodic summaries never enter the catalog.
  if (ORDER_RE.test(String(src.subject || ''))) continue;
  if (isPeriodic(src.from, src.subject)) continue;

  // Document type decides the catalog: an invoice -> Other, a release -> Main. (Label no
  // longer decides this.)
  const isInvoice = String(result.document_type || '').toLowerCase() === 'invoice';
  const catalog = isInvoice ? 'other' : 'main';

  for (const item of (result.items ?? [])) {
    // Digital releases are eliminated BEFORE the catalog (client) — no line at all. The
    // raw_entries audit still records them.
    const isDigital = DIGITAL_RE.test(String(item.format || '')) || /digital release/i.test(String(item.exclusion_reason || ''));
    if (isDigital) continue;

    const _t = cleanTitle(dropThe(item.title ?? null));
    const title = up(_t.title) + formatFeatures(item.features);

    let excluded = item.excluded === true;
    let exclusionReason = item.exclusion_reason ?? null;
    let reviewNote = null;
    if (excluded && exclusionReason && UNSURE_RE.test(exclusionReason)) {
      excluded = false;
      reviewNote = 'Kept in the catalog: the exclusion reason was not definite ("' + exclusionReason + '"). Please confirm the territory.';
      exclusionReason = null;
    }
    if (excluded && exclusionReason && /\bindie\b/i.test(exclusionReason) && !REAL_EXCL_RE.test(exclusionReason)) {
      excluded = false;
      exclusionReason = null;
    }

    const rawLabel = (item.label != null && String(item.label).trim() !== '') ? String(item.label).trim() : null;
    let itemLabel;
    if (rawLabel) {
      const k = labelKey(rawLabel);
      if (LABEL_MAP[k]) itemLabel = LABEL_MAP[k];
      else if (CANONICAL[k]) itemLabel = rawLabel;
      else { itemLabel = rawLabel; reviewNote = appendNote(reviewNote, 'Label "' + rawLabel + '" is not in the label map — confirm/add it in Settings.'); }
    } else {
      itemLabel = result.label ?? null;
    }

    const fields = {
      status: excluded ? 'excluded' : 'in_progress',
      label: itemLabel,
      catalog: catalog,
      thread_id: src.thread_id ?? null,
      artist: up(dropThe(item.artist ?? null)),
      title: title,
      format: item.format ?? null,
      genre: item.genre ?? null,
      unit: item.unit ?? null,
      ean: item.ean ?? null,
      code: toCatalogCode(item.ean),
      catalogue_no: item.catalogue_no ?? null,
      release_date: item.release_date ?? null,
      price_original: item.price ?? null,
      currency: item.currency ?? null,
      cop: item.cop ?? null,
      ppd: (function(a,b){a=a!=null?String(a).replace('.',','):null;b=b!=null?String(b).replace('.',','):null;return a&&b?a+'/'+b:(a||b||null);})(item.ppd_eur, item.rock_bottom),
      rock_bottom: item.rock_bottom ?? null,
      our_price: null,
      calculation_group: calcGroup(item, src),
      supplier_code: supplierCodeFor(itemLabel),
      confidence: item.item_confidence ?? result.overall_confidence ?? null,
      notes: item.item_notes ?? null,
    };
    const newExtra = stripBlank({
      artist_raw: item.artist_raw ?? null,
      title_variant: _t.removed.length ? _t.removed.join(' / ') : null,
      title_features: (Array.isArray(item.features) && item.features.length) ? item.features.join(' / ') : null,
      exclusion_reason: exclusionReason,
      review_note: reviewNote,
      needs_review: (result.needs_review || reviewNote) ? true : null,
      source_message_id: src.message_id ?? null,
    });

    let match = findMatch(openPool, usedOpen, fields);
    let ambiguousVia = null;
    if (match && match.ambiguous) { ambiguousVia = match.ambiguous; match = null; }

    if (!match) {
      const frozen = findMatch(sentPool, usedSent, fields);
      if (frozen && frozen.line) {
        const line = frozen.line;
        usedSent.add(line.id);
        const changes = [];
        for (const k of WATCHED) {
          if (isBlank(fields[k])) continue;
          const ov = line[k];
          if (String(isBlank(ov) ? '' : ov) !== String(fields[k])) changes.push(k + ': ' + (isBlank(ov) ? '—' : ov) + ' -> ' + fields[k]);
        }
        if (!changes.length) continue;
        const note = '[' + stamp + '] Follow-up arrived after this line was sent to Hermes, so it was NOT applied automatically: ' + changes.join('; ');
        rows.push({ json: { action: 'update', match_line_id: line.id, notes: appendNote(line.notes, note), extra: Object.assign({}, line.extra || {}, { late_update: { at: stamp, via: frozen.via, changes: changes } }) } });
        continue;
      }
    }

    if (match && match.line) {
      const line = match.line;
      usedOpen.add(line.id);
      const patch = stripBlank(fields);
      delete patch.our_price;
      delete patch.catalog;

      // Don't strip title features a feature-less follow-up (e.g. an invoice) lacks: if
      // the stored title is this title plus "(…)" extras, keep the richer stored one.
      if (patch.title && line.title) {
        const lt = String(line.title), nt = String(patch.title);
        if (lt.indexOf(nt) === 0 && lt.slice(nt.length).trim().charAt(0) === '(') delete patch.title;
      }

      let approvedNote = null;
      if (line.status === 'approved') {
        delete patch.status;
        if (excluded) approvedNote = '[' + stamp + '] This source marks the release as excluded (' + (exclusionReason || 'no reason given') + ') but the line is already approved — left approved, please review.';
      }

      const merged = appendNote(line.notes, [fields.notes, reviewNote, approvedNote].filter(Boolean).join(' '));
      if (isBlank(merged)) delete patch.notes; else patch.notes = merged;

      const mergedExtra = Object.assign({}, line.extra || {}, newExtra);
      if (!excluded) mergedExtra.exclusion_reason = null;
      patch.extra = mergedExtra;

      const mergedRow = Object.assign({}, line, patch);
      if (isBlank(mergedRow.release_date)) { patch.release_date = SENTINEL_DATE; mergedRow.release_date = SENTINEL_DATE; }
      patch.missing_fields = MANDATORY.filter(function (f) { return isBlank(mergedRow[f]); });

      rows.push({ json: Object.assign({ action: 'update', match_line_id: line.id }, patch) });
      continue;
    }

    const ek = keyEan(fields.ean);
    if (ek && createdEans.has(ek)) continue;
    const ck = keyCat(fields.catalogue_no);
    if (!ek && ck && createdCatNos.has(ck)) continue;
    if (ek) createdEans.add(ek);
    if (!ek && ck) createdCatNos.add(ck);

    const row = Object.assign({}, fields);
    row.extra = Object.assign({}, newExtra);
    if (ambiguousVia) {
      row.extra.review_note = appendNote(row.extra.review_note, 'Several open lines matched on ' + ambiguousVia + ' — created a new line instead of guessing which one to update.');
      row.extra.needs_review = true;
    }
    row.notes = appendNote(fields.notes, reviewNote);
    if (isBlank(row.release_date)) { row.release_date = SENTINEL_DATE; row.extra.release_date_tbc = true; }
    row.missing_fields = MANDATORY.filter(function (f) { return isBlank(row[f]); });
    rows.push({ json: Object.assign({ action: 'create', match_line_id: null }, row) });
  }
}
return rows;

