          label: b.label != null ? b.label : null,
          needs_review: b.needs_review != null ? b.needs_review : false,
          review_reasons: b.review_reasons != null ? b.review_reasons : [],
          items: b.items,
        },
        ai_parts: b.parts,
        source_rows: b.rows,
        source_body: bodyFull,
        source_attachments: attFull,
      },
    } };
  });
}

const inputs = $input.all();
function srcFor(i) {
  try { return $("Chunk Source").itemMatching(i).json; }
